script:
(function () {
  'use strict';
  // RV loan: monthly payment from the RV's price, or the price a monthly budget covers, plus an
  // estimate of when the loan balance drops below the RV's value.
  //   Down payment D = d% of price or a dollar amount.
  //   Taxable amount = price - trade-in value (when the trade-in credit box is ticked), never below 0.
  //   Loan = price - D - trade-in + owed on trade-in + service contract/add-ons
  //          (+ sales tax and fees when they are financed).
  //   Payment: M = L x i / (1 - (1 + i)^-n), i = APR / 12, n = years x 12 (M = L / n at 0%).
  //   Estimated value after m months = price x (1 - yearly depreciation)^(m / 12).
  //   Price mode: L = M(1 - (1 + i)^-n) / i, then the matching price is found by bisection.
  // Verified in Node (scratchpad tests/b3auto): $90,000 RV, 15% down, 6% tax and $1,500 fees financed
  //   -> loan $83,400; at 8% for 15 years = $797.01/mo, total interest $60,062.49 (closed form
  //   PMT x n - L); price mode on that payment returns $90,000.00; a $13,500 dollar down payment gives
  //   the same loan; underwater months match an independent month-by-month check; 0% for 15 years =
  //   L / 180; no NaN or Infinity on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function loanFromPayment(pmt, annualRate, months) {
    var i = annualRate / 12;
    if (i === 0) return pmt * months;
    return pmt * (1 - Math.pow(1 + i, -months)) / i;
  }

  // Everything that depends on the RV's price.
  function costs(price, o) {
    var down = o.downPercent ? price * o.down / 100 : o.down;
    var tax = Math.max(0, price - (o.tradeCredit ? o.trade : 0)) * o.taxRate / 100;
    var loan = price - down - o.trade + o.owed + o.addons + (o.finance ? tax + o.fees : 0);
    return { price: price, down: down, tax: tax, loan: loan };
  }

  // RV price whose loan equals the target, by bisection. NaN when even a $0 RV needs a bigger loan.
  function priceForLoan(target, o) {
    if (costs(0, o).loan > target) return NaN;
    var lo = 0, hi = 1;
    while (costs(hi, o).loan < target && hi < 1e10) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (costs(mid, o).loan < target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function amortize(loan, annualRate, months) {
    var pay = monthlyPayment(loan, annualRate, months);
    var i = annualRate / 12, bal = loan, rows = [], totalInterest = 0;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i;
      var principal = Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, interest: interest, principal: principal, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest };
  }

  function valueAt(price, dep, months) { return price * Math.pow(1 - dep, months / 12); }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['rvMain', 'rvLoan', 'rvInterest', 'rvTotalCost', 'rvPriceOut', 'rvPaymentOut', 'rvDownOut', 'rvTax',
     'rvUpfront', 'rvTotalPayments', 'rvUnderwater'].forEach(function (id) { setText(id, '–'); });
    el('rvNegative').hidden = true;
    el('rvSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('rvScheduleHead'), body = el('rvSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [], monthly = el('rvView').value === 'month';
    head.innerHTML = '<tr><th scope="col">' + (monthly ? 'Month' : 'Year') + '</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Ending balance</th><th scope="col">Estimated RV value</th><th scope="col">Equity</th></tr>';
    var p = 0, intr = 0;
    last.rows.forEach(function (row, idx) {
      p += row.principal; intr += row.interest;
      if (monthly || row.n % 12 === 0 || idx === last.rows.length - 1) {
        var value = valueAt(last.price, last.dep, row.n), equity = value - row.balance;
        html.push('<tr><td>' + (monthly ? row.n : Math.ceil(row.n / 12)) + '</td><td>' + money.format(p) + '</td><td>' +
          money.format(intr) + '</td><td>' + money.format(row.balance) + '</td><td>' + money.format(value) + '</td><td>' +
          (equity < 0 ? '−' : '') + money.format(Math.abs(equity)) + '</td></tr>');
        p = 0; intr = 0;
      }
    });
    body.innerHTML = html.join('');
  }

  function update() {
    var priceMode = el('rvMode').value === 'price';
    el('rvPriceWrap').hidden = priceMode;
    el('rvBudgetWrap').hidden = !priceMode;
    var o = {
      down: read('rvDown', true), downPercent: el('rvDownUnit').value === 'percent', trade: read('rvTrade', true),
      owed: read('rvOwed', true), taxRate: read('rvTaxRate', true), fees: read('rvFees', true),
      addons: read('rvAddons', true), finance: el('rvFinance').checked, tradeCredit: el('rvTradeCredit').checked
    };
    var price = read('rvPrice'), budget = read('rvBudget'), rate = read('rvRate'), years = read('rvTerm'),
        dep = read('rvDep', true);
    setText('rvDownHint', o.downPercent ? 'Percent of the RV price. Lenders often ask for 10% to 20%.' : 'Cash you pay toward the RV at purchase.');
    var error = el('rvError'), msg = '';
    if (!priceMode && (isNaN(price) || price <= 0)) msg = 'Enter an RV price greater than $0.';
    else if (priceMode && (isNaN(budget) || budget <= 0)) msg = 'Enter a monthly payment greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(years) || years < 1 || years > 25 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 25 whole years.';
    else if (['down', 'trade', 'owed', 'taxRate', 'fees', 'addons'].some(function (k) { return isNaN(o[k]) || o[k] < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.downPercent && o.down >= 100) msg = 'Enter a down payment below 100% of the price.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (isNaN(dep) || dep < 0 || dep >= 100) msg = 'Enter a yearly depreciation from 0% to 99%.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var months = years * 12, r = rate / 100, c;
    if (priceMode) {
      var p = priceForLoan(loanFromPayment(budget, r, months), o);
      if (!(p > 0) || !isFinite(p)) msg = 'That payment is too small to cover the costs and trade-in balance you are financing.';
      else c = costs(p, o);
    } else {
      c = costs(price, o);
      if (c.loan <= 0.005) msg = 'Your down payment and trade-in cover the full cost, so there is nothing to finance.';
    }
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var a = amortize(c.loan, r, months), d = dep / 100;
    var upfront = c.down + (o.finance ? 0 : c.tax + o.fees);
    // Months in which the balance is above the estimated value (month 0 = the day you buy).
    var first = c.loan > c.price ? 0 : -1, lastUnder = first;
    a.rows.forEach(function (row) {
      if (row.balance > valueAt(c.price, d, row.n) + 0.005) { if (first < 0) first = row.n; lastUnder = row.n; }
    });
    setText('rvMainLabel', priceMode ? 'RV price you can afford' : 'Monthly payment');
    setText('rvMain', money.format(priceMode ? c.price : a.payment));
    setText('rvLoan', money.format(c.loan));
    setText('rvInterest', money.format(a.totalInterest));
    setText('rvTotalCost', money.format(c.price + c.tax + o.fees + o.addons + a.totalInterest));
    setText('rvPriceOut', money.format(c.price));
    setText('rvPaymentOut', money.format(a.payment));
    setText('rvDownOut', money.format(c.down));
    setText('rvTax', money.format(c.tax));
    setText('rvUpfront', money.format(upfront));
    setText('rvTotalPayments', money.format(c.loan + a.totalInterest));
    setText('rvUnderwater', first < 0 ? 'Never, on these estimates' :
      (first === 0 ? 'From the start' : 'From month ' + first) + ' to month ' + lastUnder + ' (' + duration(lastUnder) + ')');
    el('rvNegative').hidden = !(o.owed > o.trade);
    setText('rvNegativeAmount', money.format(Math.max(0, o.owed - o.trade)));
    last = { rows: a.rows, price: c.price, dep: d };
    renderSchedule();
  }

  function switchDownUnit() {
    var v = read('rvDown', true), price = el('rvMode').value === 'price' ? NaN : read('rvPrice');
    if (!isNaN(v) && price > 0) {
      el('rvDown').value = el('rvDownUnit').value === 'percent' ? String(Math.round(v / price * 10000) / 100) : String(Math.round(price * v / 100));
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rvForm');
    if (!form) return;
    el('rvDownUnit').addEventListener('change', switchDownUnit);
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('rvView').addEventListener('change', renderSchedule);
    update();
  });
})();
